"""Pinned BWAPI4.4.0/OpenBW Infestation, infested units and suicide splash facts."""
import re,json,hashlib,sys
from pathlib import Path
root=Path(sys.argv[1]if len(sys.argv)>1 else 'work/sources');u=(root/'unit.cpp').read_text();t=(root/'tech.cpp').read_text();w=(root/'weapon.cpp').read_text();e=(root/'bwgame.h').read_text()
def body(s,n):return re.search(re.escape(n)+r'\[[^\]]+\]\s*=\s*\{(.*?)\};',re.sub(r'//[^\n]*','',s),re.S)[1]
def nums(s,n):return [float(x)for x in re.findall(r'-?\d+(?:\.\d+)?',body(s,n))]
def words(s,n):return re.findall(r'\b[A-Za-z_][A-Za-z_0-9]*\b',body(s,n))
def names(s):return re.findall(r'"([^"]*)"',body(s,'typeNames'))
un=names(u);tn=names(t);wn=names(w);dims=[[int(x)for x in re.findall(r'\d+',v)]for v in re.findall(r'\{([^{}]+)\}',body(u,'unitDimensions'))];flags=body(u,'unitFlags').split(',');units=[];profiles=[];traits=[]
for name in ['Zerg_Infested_Command_Center','Zerg_Infested_Terran']:
 i=un.index(name);values={k:nums(u,k)[i]for k in ['defaultOreCost','defaultGasCost','defaultTimeCost','defaultMaxHP','defaultMaxSP','defaultArmorAmount','unitSupplyProvided','unitSupplyRequired','unitTopSpeeds','sightRangeTiles']};values={k:int(v)if v.is_integer()else v for k,v in values.items()};units.append({'name':name,'bwapiId':i,**values,'dimensions':dims[i]});profiles.append({'name':name,'size':words(u,'unitSize')[i].lower(),'bounds':dims[i][2:],'groundWeapon':words(u,'groundWeapon')[i],'airWeapon':words(u,'airWeapon')[i],'hits':int(nums(u,'groundWeaponHits')[i])});traits.append({'name':name,'spaceRequired':int(nums(u,'unitSpaceRequired')[i]),'spaceProvided':int(nums(u,'unitSpaceProvided')[i]),'flyer':'Flyer'in flags[i],'detector':'Detector'in flags[i],'permanentCloak':False})
j=wn.index('Suicide_Infested_Terran');weapon={'name':wn[j],'bwapiId':j,**{k:int(nums(w,k)[j])for k in ['defaultWpnDamageAmt','defaultWpnDamageBonus','wpnDamageCooldowns','wpnDamageFactor','wpnMinRange','wpnMaxRange']},'damageType':words(w,'damageType')[j],'upgrade':words(w,'upgrade')[j]};splash={k:int(nums(w,k)[j])for k in ['wpnSplashRangeInner','wpnSplashRangeMid','wpnSplashRangeOuter']};splash.update(explosionType=words(w,'explosionType')[j],targetFlags=[v.strip()for v in body(w,'wpnFlags').split(',')[j].split('|')]);k=tn.index('Infestation');area=e[e.index('bool unit_can_be_infested'):e.index('bool unit_can_attack_target')];assert 'u_completed(u)'in area and 'unit_hp_percent(u) < 50'in area;assert 'return hp * 100 / max_hp'in e;area=e[e.index('void order_InfestedCommandCenter'):e.index('void order_SuicideUnit')];assert 'set_unit_owner(u, queen->owner, true)'in area and 'cancel_build_queue(u)'in area and 'set_unit_hp(u, u->unit_type->hitpoints)'in area
assert 'bool damages_allies = !is_air_splash'in e and 'else if (!u_burrowed(target))'in e
out={'source':{'bwapiTag':'v4.4.0','openbwCommit':json.loads((root/'openbw-commit.json').read_text())['sha'],'sha256':{n:hashlib.sha256((root/n).read_bytes()).hexdigest()for n in ['unit.cpp','tech.cpp','weapon.cpp','bwgame.h']}},'units':units,'profiles':profiles,'traits':traits,'weapons':[weapon],'technology':{'name':'Infestation','id':'infestation','energy':int(nums(t,'defaultEnergyCost')[k]),'target':'terran-command-center','completed':True,'hpPercentBelow':50,'researchRequired':False},'splash':splash,'originalTiming':{'conversionDelayFrames':3,'queenHiddenFrames':60},'burrowable':['zerg-infested-terran']}
Path('app/stark-rift/data/infestation-original.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n');print(json.dumps({'units':units,'weapon':weapon,'splash':splash,'tech':out['technology']},ensure_ascii=False))
